+            throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);
+        }
+        PageKind kind = parseKind(command.kind());
+        if (!capabilities.supports(kind)) {
+            throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);
+        }
