+            roundBudget = settings.nextCallBudget();
+        }
+    }
+
+    private List<ToolResult> execute(
+            List<ToolCall> calls, Map<String, AssistantTool> tools, FactPack pack) {
+        List<ToolResult> results = new ArrayList<>();
