+
+        List<Evidence> facts() {
+            return List.copyOf(facts);
+        }
+
+        /** {@code room}과 남은 자리 중 작은 만큼만 받는다. 돌려주는 것은 실제로 들어간(id가 매겨진) 근거다. */
+        List<Evidence> add(List<Evidence> incoming, int room) {
+            List<Evidence> source = incoming == null ? List.of() : incoming;
