+                                                + source.size()
+                                                + "개 중 "
+                                                + take
+                                                + "개)",
+                                        null,
+                                        null,
+                                        EvidenceKind.TEXT)));
+            }
+            return added;
+        }
+
+        private Evidence assign(Evidence fact) {
+            Evidence numbered = fact.withId("F" + (facts.size() + 1));
+            facts.add(numbered);
+            return numbered;
+        }
+    }
