+    static String dateArgument(Case c, String arg, List<Evidence> facts) {
+        String peak = valueOf(facts, "하락 시작(고점) 날짜");
+        String trough = valueOf(facts, "가장 크게 줄어든 날짜");
+        if (trough != null) {
