+import { Bot } from 'lucide-react'
+import { Popover } from 'radix-ui'
+import {
+  type CSSProperties,
+  type PointerEvent as ReactPointerEvent,
+  useCallback,
+  useEffect,
+  useId,
+  useRef,
+  useState,
+} from 'react'
+import { AssistantBubble, useAssistantConversation } from './AssistantBubble'
+import type { AssistantPage } from './assistantPageContext'
+import styles from './assistant.module.css'
+import {
+  DRAG_THRESHOLD_PX,
+  type FabPosition,
+  clampFabY,
+  loadFabPosition,
+  saveFabPosition,
+  snapSide,
+} from './fabPosition'
+
+const NARROW_QUERY = '(max-width: 600px)'
+
+/** 좁은 화면(≤600px)이면 끌기 없이 우측 하단 고정 + 바닥 시트다(FR-002·FR-003). jsdom 처럼 `matchMedia`가 없으면 넓은 화면이다. */
+function useNarrowScreen(): boolean {
+  const [narrow, setNarrow] = useState(() => window.matchMedia?.(NARROW_QUERY).matches ?? false)
+  useEffect(() => {
+    const query = window.matchMedia?.(NARROW_QUERY)
+    if (!query) return undefined
+    const update = () => setNarrow(query.matches)
+    update()
+    query.addEventListener('change', update)
+    return () => query.removeEventListener('change', update)
+  }, [])
+  return narrow
+}
+
+type DragState = { pointerId: number; startX: number; startY: number; dx: number; dy: number }
