+    if (suppressClickRef.current) {
+      suppressClickRef.current = false
+      return
+    }
+    setOpen((current) => !current)
+  }
+
+  const style: CSSProperties | undefined = narrow
+    ? undefined
+    : {
+        top: position.y,
+        [position.side]: 'var(--thorp-page-gutter, 16px)',
+        transform: drag ? `translate(${drag.dx}px, ${drag.dy}px)` : undefined,
+      }
+
+  const button = (
+    <button
+      ref={buttonRef}
+      type="button"
+      className={styles.fab}
+      style={style}
+      data-side={position.side}
+      data-narrow={narrow || undefined}
+      data-dragging={drag ? 'true' : undefined}
+      aria-label="질문하기"
+      aria-haspopup="dialog"
+      aria-expanded={open}
+      aria-controls={open ? panelId : undefined}
+      onPointerDown={onPointerDown}
+      onPointerMove={onPointerMove}
+      onPointerUp={onPointerUp}
+      onPointerCancel={() => setDrag(null)}
+      onClick={onClick}
+    >
+      <Bot size={24} aria-hidden="true" />
+    </button>
+  )
+
+  const bubble = (
+    <AssistantBubble conversation={conversation} onClose={close} autoFocus={narrow} />
+  )
+
+  if (narrow) {
+    return (
+      <>
+        {button}
+        {open ? (
+          <BottomSheet id={panelId} sheetRef={sheetRef} buttonRef={buttonRef} onClose={close}>
+            {bubble}
+          </BottomSheet>
+        ) : null}
+      </>
+    )
+  }
+
+  return (
+    <Popover.Root
+      open={open}
+      onOpenChange={(next) => {
+        if (!next) close()
+      }}
+    >
+      <Popover.Anchor asChild>{button}</Popover.Anchor>
+      <Popover.Portal>
+        <Popover.Content
+          id={panelId}
+          className={styles.popover}
+          side={position.side === 'left' ? 'right' : 'left'}
+          align="end"
+          sideOffset={8}
+          collisionPadding={16}
+          aria-label="질문하기"
+          data-shell="popover"
+          onOpenAutoFocus={(event) => {
+            event.preventDefault()
+            document.getElementById(panelId)?.querySelector('textarea')?.focus()
+          }}
+          onCloseAutoFocus={(event) => {
+            event.preventDefault()
+            buttonRef.current?.focus()
+          }}
+        >
+          {bubble}
+        </Popover.Content>
+      </Popover.Portal>
+    </Popover.Root>
+  )
+}
+
+/** 좁은 화면의 바닥 시트. 비모달이라 뒤 화면을 막지 않고, Escape·바깥 누르기로 닫힌다. */
+function BottomSheet({
+  id,
+  sheetRef,
+  buttonRef,
+  onClose,
+  children,
+}: {
+  id: string
+  sheetRef: React.RefObject<HTMLDivElement | null>
+  buttonRef: React.RefObject<HTMLButtonElement | null>
+  onClose: () => void
+  children: React.ReactNode
+}) {
+  useEffect(() => {
+    const onKeyDown = (event: KeyboardEvent) => {
+      if (event.key === 'Escape') onClose()
+    }
+    const onPointerDown = (event: PointerEvent) => {
