+/* '지금 국내 시장' 지수 카드. 한 줄에 이름(왼쪽)·값과 변화(오른쪽), 출처는 아래 오른쪽이다. */
+.market {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+}
+
+.cards {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.card {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 12px;
+  padding: var(--thorp-pad-inset, 12px 14px);
+  border: 1px solid var(--thorp-line);
+  border-radius: var(--thorp-radius-inset, 8px);
+  background: var(--thorp-surface-muted);
+}
+
+.name {
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-small, 0.78rem);
+  font-weight: 600;
+  white-space: nowrap;
+}
+
+.reading {
+  display: inline-flex;
+  align-items: baseline;
+  gap: 8px;
+  color: var(--thorp-foreground);
+  font-variant-numeric: tabular-nums;
+  white-space: nowrap;
+}
+
+.reading strong {
+  font-family: var(--thorp-font-number, inherit);
+  font-size: var(--thorp-text-heading, 1.08rem);
+  font-weight: var(--thorp-number-weight, 650);
+}
+
+.reading em {
+  font-size: var(--thorp-text-caption, 0.72rem);
+  font-style: normal;
+  font-weight: 600;
+}
+
+/* 오르내림 색: 값과 변화 모두 상승 빨강·하락 파랑. */
+.reading[data-direction='up'] {
+  color: var(--thorp-up);
+}
+
+.reading[data-direction='down'] {
+  color: var(--thorp-down);
+}
+
+.source,
+.note {
+  margin: 0;
+  color: var(--thorp-muted);
+  font-size: var(--thorp-text-caption, 0.72rem);
+}
+
+.source {
+  text-align: right;
+}

@@ -0,0 +1,70 @@
+/* 시장 흐름 뉴스 카드. 과거 시장 카드 옆에 놓이며 다른 카드와 같은 면·모서리다. */
+.card {
+  display: flex;
+  flex-shrink: 0;
+  flex-direction: column;
+  gap: 12px;
+  padding: var(--thorp-pad-card, 18px);
+  border: 1px solid var(--thorp-line);
+  border-radius: var(--thorp-radius-card, 12px);
+  background: var(--thorp-surface);
+}
+
+.title {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  margin: 0;
+  font-size: var(--thorp-text-body, 0.98rem);
+  font-weight: 650;
+}
+
+.title svg {
+  flex-shrink: 0;
+  color: var(--thorp-accent-soft);
+}
+
+/* 섹터별로 보기. 옆 과거 시장 카드의 분야 칩과 같은 모양이다. */
+.filter {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 8px;
+}
+
+.chip {
+  display: inline-flex;
+  align-items: center;
+  min-height: var(--thorp-control-sm, 32px);
+  padding: 0 12px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: var(--thorp-radius-control, 6px);
+  background: transparent;
+  color: var(--thorp-copy);
+  font: inherit;
+  font-size: var(--thorp-text-small, 0.78rem);
+  cursor: pointer;
+  transition: border-color 150ms ease, background-color 150ms ease, color 150ms ease;
+}
+
+.chip:hover {
+  border-color: var(--thorp-line-control-hover);
+  color: var(--thorp-foreground);
+}
+
+.chip[aria-pressed='true'] {
+  border-color: var(--thorp-accent-soft);
+  background: var(--thorp-accent-muted);
+  color: var(--thorp-foreground);
+  font-weight: 600;
+}
+
+.chip:focus-visible {
+  outline: var(--thorp-focus-outline-compact);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .chip {
+    transition: none;
+  }
+}

